/// One selected positive-length cusp-circle/mapped-curve overlap.
///
/// The other source range remains in ascending Bezier-parameter order.
/// Its endpoint locations identify exact cusp endpoints when the overlap is
/// clipped by the selected diameter; an interior endpoint is mapped lazily by
/// the pair-shared parameter authority. `orientation` compares
/// increasing parameters on the two supporting carriers, independently of
/// either boundary fragment's traversal bit.
#[derive(Clone, Debug)]
#[allow(dead_code)]
pub(crate) struct BezierAlgebraicCuspSemicircleMappedOverlap2 {
    other_range: BezierParameterRange2,
    cusp_start: BezierAlgebraicCuspSemicircleParameter2,
    cusp_end: BezierAlgebraicCuspSemicircleParameter2,
    orientation: RationalBezierOverlapOrientation2,
    parameter_map: BezierAlgebraicCuspSemicircleMappedOverlapMap2,
    map_reversed: bool,
}

impl PartialEq for BezierAlgebraicCuspSemicircleMappedOverlap2 {
    fn eq(&self, other: &Self) -> bool {
        self.other_range == other.other_range
            && self.cusp_start.shares_exact_evidence(&other.cusp_start)
            && self.cusp_end.shares_exact_evidence(&other.cusp_end)
            && self.orientation == other.orientation
    }
}

#[allow(dead_code)]
impl BezierAlgebraicCuspSemicircleMappedOverlap2 {
    pub(crate) const fn other_range(&self) -> &BezierParameterRange2 {
        &self.other_range
    }

    pub(crate) fn cusp_start_parameter(&self) -> BezierAlgebraicCuspSemicircleParameter2 {
        self.cusp_start.clone()
    }

    pub(crate) fn cusp_end_parameter(&self) -> BezierAlgebraicCuspSemicircleParameter2 {
        self.cusp_end.clone()
    }

    pub(crate) const fn orientation(&self) -> RationalBezierOverlapOrientation2 {
        self.orientation
    }

    fn cusp_parameter_at_other_endpoint(
        &self,
        other_start: bool,
    ) -> BezierAlgebraicCuspSemicircleParameter2 {
        let cusp_start =
            other_start == (self.orientation == RationalBezierOverlapOrientation2::Same);
        if cusp_start {
            self.cusp_start_parameter()
        } else {
            self.cusp_end_parameter()
        }
    }

    fn other_parameter_at_cusp_endpoint(&self, cusp_start: bool) -> BezierParameter2 {
        let other_start =
            cusp_start == (self.orientation == RationalBezierOverlapOrientation2::Same);
        if other_start {
            self.other_range.start().clone()
        } else {
            self.other_range.end().clone()
        }
    }

    fn map_policy(&self) -> CurveContext {
        match &self.parameter_map {
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(map) => map.data.policy,
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(map) => map.data.policy,
        }
    }

    /// Maps one parameter on this published overlap to its compact
    /// cusp-circle parameter without constructing another selected-root field.
    pub(crate) fn cusp_parameter_for_other(
        &self,
        parameter: &BezierParameter2,
        policy: &CurveContext,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameter2>> {
        if self.map_policy() != *policy {
            return Err(CurveError::Topology(
                "mapped cusp overlap was replayed under a different predicate policy".into(),
            ));
        }
        for (endpoint, other_start) in [
            (self.other_range.start(), true),
            (self.other_range.end(), false),
        ] {
            match parameter.same_value(endpoint, policy)? {
                Classification::Decided(true) => {
                    return Ok(Classification::Decided(
                        self.cusp_parameter_at_other_endpoint(other_start),
                    ));
                }
                Classification::Decided(false) => {}
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }
        let map_parameter = if self.map_reversed {
            parameter.unit_complement()
        } else {
            parameter.clone()
        };
        let parameter = match &self.parameter_map {
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(map) => {
                map.mapped_parameter(BezierAlgebraicCuspSemicircleRationalMapContact2 {
                    other_parameter: map_parameter,
                    location: BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                    correlation: BezierAlgebraicCuspSemicircleRationalCorrelation2::Independent,
                })
            }
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(map) => {
                let contact = BezierAlgebraicCuspSemicircleParallelContact2 {
                    parallel_parameter: map_parameter,
                    tangent_cross_sign: None,
                    location: BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                    correlated: false,
                };
                map.contact_parameter(&contact)
            }
        };
        Ok(Classification::Decided(parameter))
    }

    /// Inverts this overlap at one compact cusp parameter.
    ///
    /// Cuts authored by this same map reuse their retained analytic parameter.
    /// An independently represented `Real` cut projects the exact radial-dot
    /// equality in the retained cusp field and replays its unsquared branch.
    /// General unrelated mapped fields remain explicit until the region
    /// carrier can retain their cross-field correspondence directly.
    pub(crate) fn other_parameter_for_cusp(
        &self,
        parameter: &BezierAlgebraicCuspSemicircleParameter2,
        policy: &CurveContext,
    ) -> CurveResult<Classification<BezierParameter2>> {
        parameter.validate_policy(policy)?;
        if self.map_policy() != *policy {
            return Err(CurveError::Topology(
                "mapped cusp overlap was replayed under a different predicate policy".into(),
            ));
        }
        for (endpoint, cusp_start) in [(&self.cusp_start, true), (&self.cusp_end, false)] {
            match parameter.cmp_by_refinement(endpoint, policy)? {
                Classification::Decided(std::cmp::Ordering::Equal) => {
                    return Ok(Classification::Decided(
                        self.other_parameter_at_cusp_endpoint(cusp_start),
                    ));
                }
                Classification::Decided(std::cmp::Ordering::Less | std::cmp::Ordering::Greater) => {
                }
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }

        if let BezierAlgebraicCuspSemicircleParameter2::Mapped(data) = parameter {
            let same_map_parameter = match (&self.parameter_map, data.as_ref()) {
                (
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(overlap_map),
                    BezierAlgebraicCuspSemicircleMappedParameterData2::Rational { map, contact },
                ) => map
                    .parameterization_orientation(overlap_map)
                    .map(|orientation| (contact.other_parameter.clone(), orientation)),
                (
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(overlap_map),
                    BezierAlgebraicCuspSemicircleMappedParameterData2::Parallel { map, contact },
                ) => map
                    .parameterization_orientation(overlap_map)
                    .map(|orientation| (contact.parallel_parameter.clone(), orientation)),
                _ => None,
            };
            if let Some((parameter, orientation)) = same_map_parameter {
                let reverse = self.map_reversed
                    != (orientation == RationalBezierOverlapOrientation2::Reversed);
                return Ok(Classification::Decided(if reverse {
                    parameter.unit_complement()
                } else {
                    parameter
                }));
            }

            if let BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(target) =
                &self.parameter_map
                && let Some((source, contact)) = data.coincident_rational_source()
            {
                if source.data.policy != *policy {
                    return Err(CurveError::Topology(
                        "mapped rational source used a different predicate policy".into(),
                    ));
                }
                match RationalBezierOverlapParameterCorrespondence2::map_parameter_between_curves(
                    &source.data.curve,
                    &target.data.curve,
                    &contact.other_parameter,
                    policy,
                )? {
                    Classification::Decided(Some(parameter)) => {
                        let parameter = if self.map_reversed {
                            parameter.unit_complement()
                        } else {
                            parameter
                        };
                        return retain_direct_overlap_parameter(
                            parameter,
                            &self.other_range,
                            policy,
                        );
                    }
                    Classification::Decided(None) => {}
                    Classification::Uncertain(reason) => {
                        return Ok(Classification::Uncertain(reason));
                    }
                }
            }

            if let BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(target) =
                &self.parameter_map
                && let Some((source, contact, first, source_reversed)) =
                    data.coincident_pair_source()
            {
                let target_reversed = source_reversed
                    ^ (self.orientation == RationalBezierOverlapOrientation2::Reversed)
                    ^ self.map_reversed;
                let candidates = match source.rational_parameters_for_contact(
                    contact,
                    first,
                    &target.data.curve,
                    target_reversed,
                    policy,
                )? {
                    Classification::Decided(candidates) => candidates,
                    Classification::Uncertain(reason) => {
                        return Ok(Classification::Uncertain(reason));
                    }
                };
                return retain_unique_overlap_parameter(
                    candidates,
                    &self.other_range,
                    self.map_reversed,
                    true,
                    policy,
                    |_| Ok(Classification::Decided(RealSign::Zero)),
                );
            }

            if let BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(target) =
                &self.parameter_map
                && let Some((source, contact, first, source_reversed)) =
                    data.coincident_pair_source()
            {
                let target_reversed = source_reversed
                    ^ (self.orientation == RationalBezierOverlapOrientation2::Reversed)
                    ^ self.map_reversed;
                let candidates = match source.parallel_parameters_for_contact(
                    contact,
                    first,
                    &target.data.parallel,
                    target_reversed,
                    policy,
                )? {
                    Classification::Decided(candidates) => candidates,
                    Classification::Uncertain(reason) => {
                        return Ok(Classification::Uncertain(reason));
                    }
                };
                return retain_unique_overlap_parameter(
                    candidates,
                    &self.other_range,
                    self.map_reversed,
                    true,
                    policy,
                    |_| Ok(Classification::Decided(RealSign::Zero)),
                );
            }

            if let Some((source, start, evidence_policy)) = data.coincident_pair_endpoint_source() {
                if evidence_policy != *policy {
                    return Err(CurveError::Topology(
                        "cusp-pair overlap endpoint was replayed under a different predicate policy"
                            .into(),
                    ));
                }
                let parameter = if start { Real::zero() } else { Real::one() };
                let candidates = match &self.parameter_map {
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(target) => {
                        rational_parameters_for_cusp_endpoint(
                            source,
                            &parameter,
                            &target.data.curve,
                            policy,
                        )?
                    }
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(target) => {
                        parallel_parameters_for_cusp_endpoint(
                            source,
                            &parameter,
                            &target.data.parallel,
                            policy,
                        )?
                    }
                };
                let candidates = match candidates {
                    Classification::Decided(candidates) => candidates,
                    Classification::Uncertain(reason) => {
                        return Ok(Classification::Uncertain(reason));
                    }
                };
                return retain_unique_overlap_parameter(
                    candidates,
                    &self.other_range,
                    self.map_reversed,
                    true,
                    policy,
                    |_| Ok(Classification::Decided(RealSign::Zero)),
                );
            }

            let equivalent_cross_map_parameter = match (&self.parameter_map, data.as_ref()) {
                (
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(target),
                    BezierAlgebraicCuspSemicircleMappedParameterData2::Parallel {
                        map: source,
                        contact,
                    },
                ) => {
                    match rational_parallel_parameter_orientation_at_cut(
                        target,
                        source,
                        &contact.parallel_parameter,
                        false,
                        policy,
                    )? {
                        Classification::Decided(Some(orientation)) => {
                            Some((contact.parallel_parameter.clone(), orientation))
                        }
                        Classification::Decided(None) => None,
                        Classification::Uncertain(reason) => {
                            return Ok(Classification::Uncertain(reason));
                        }
                    }
                }
                (
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(target),
                    BezierAlgebraicCuspSemicircleMappedParameterData2::Rational {
                        map: source,
                        contact,
                    },
                ) => {
                    match rational_parallel_parameter_orientation_at_cut(
                        source,
                        target,
                        &contact.other_parameter,
                        true,
                        policy,
                    )? {
                        Classification::Decided(Some(orientation)) => {
                            Some((contact.other_parameter.clone(), orientation))
                        }
                        Classification::Decided(None) => None,
                        Classification::Uncertain(reason) => {
                            return Ok(Classification::Uncertain(reason));
                        }
                    }
                }
                _ => None,
            };
            if let Some((parameter, orientation)) = equivalent_cross_map_parameter {
                let reverse = self.map_reversed
                    != (orientation == RationalBezierOverlapOrientation2::Reversed);
                let parameter = if reverse {
                    parameter.unit_complement()
                } else {
                    parameter
                };
                return retain_direct_overlap_parameter(parameter, &self.other_range, policy);
            }

            if let Some(source) = data.coincident_tangent_source() {
                if source.policy() != *policy {
                    return Err(CurveError::Topology(
                        "mapped tangent source used a different predicate policy".into(),
                    ));
                }
                let source_tangent = source.tangent_power_basis()?;
                let target_tangent = match &self.parameter_map {
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(target) => {
                        rational_parametric_tangent_numerator(
                            target.data.curve.homogeneous_power_basis()?,
                        )
                    }
                    BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(target) => {
                        let differential = target.data.parallel.differential()?;
                        [
                            differential.tangent_x.clone(),
                            differential.tangent_y.clone(),
                        ]
                    }
                };
                let candidates = match mapped_circle_tangent_parameter_candidates(
                    source.parameter(),
                    &source_tangent,
                    &target_tangent,
                    policy,
                )? {
                    Classification::Decided(candidates) => candidates,
                    Classification::Uncertain(reason) => {
                        return Ok(Classification::Uncertain(reason));
                    }
                };
                return retain_unique_overlap_parameter(
                    candidates,
                    &self.other_range,
                    self.map_reversed,
                    false,
                    policy,
                    |_| Ok(Classification::Decided(RealSign::Zero)),
                );
            }

            match parameter.represented_rational_value(policy)? {
                Classification::Decided(Some(parameter)) => {
                    return self.other_parameter_for_cusp(
                        &BezierAlgebraicCuspSemicircleParameter2::Exact(parameter),
                        policy,
                    );
                }
                Classification::Decided(None) => {}
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }

        let BezierAlgebraicCuspSemicircleParameter2::Exact(parameter) = parameter else {
            return Ok(Classification::Uncertain(UncertaintyReason::Unsupported));
        };
        match &self.parameter_map {
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Rational(map) => {
                rational_overlap_parameter_for_exact_cusp(
                    map,
                    parameter,
                    &self.other_range,
                    self.map_reversed,
                    policy,
                )
            }
            BezierAlgebraicCuspSemicircleMappedOverlapMap2::Parallel(map) => {
                parallel_overlap_parameter_for_exact_cusp(
                    map,
                    parameter,
                    &self.other_range,
                    self.map_reversed,
                    policy,
                )
            }
        }
    }
}

fn rational_overlap_parameter_for_exact_cusp(
    map: &BezierAlgebraicCuspSemicircleRationalParameterMap2,
    parameter: &Real,
    range: &BezierParameterRange2,
    map_reversed: bool,
    policy: &CurveContext,
) -> CurveResult<Classification<BezierParameter2>> {
    let map = &map.data;
    let BezierParameter2::Algebraic(cusp_parameter) = &map.cusp_parameter else {
        return Err(CurveError::Topology(
            "cusp/rational map lost its retained cusp root".into(),
        ));
    };
    let one_minus = Real::one() - parameter;
    let denominator = &one_minus * &one_minus + parameter * parameter;
    match real_sign(&denominator, policy) {
        Some(RealSign::Positive) => {}
        Some(RealSign::Zero | RealSign::Negative) => {
            return Err(CurveError::Topology(
                "semicircle inverse-map denominator was not positive".into(),
            ));
        }
        None => return Ok(Classification::Uncertain(UncertaintyReason::RealSign)),
    }
    let radial_coefficient = Real::one() - Real::from(2_i8) * parameter;
    let incidence = bivariate_scaled_difference(
        &map.diameter_side,
        &denominator,
        &map.radius_squared_denominator,
        &radial_coefficient,
    );
    let incidence = match reduce_algebraic_cusp_bivariate(incidence, cusp_parameter, policy)? {
        Classification::Decided(incidence) => incidence,
        Classification::Uncertain(reason) => return Ok(Classification::Uncertain(reason)),
    };
    let candidates =
        match algebraic_cusp_reduced_fiber_parameters(&incidence, cusp_parameter, policy)? {
            Classification::Decided(BezierAlgebraicCuspFiberProjection2::Parameters(
                candidates,
            )) => candidates,
            Classification::Decided(
                BezierAlgebraicCuspFiberProjection2::IdenticallyZero
                | BezierAlgebraicCuspFiberProjection2::Degenerate,
            ) => return Ok(Classification::Uncertain(UncertaintyReason::Unsupported)),
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
    retain_unique_overlap_parameter(candidates, range, map_reversed, true, policy, |_| {
        Ok(Classification::Decided(RealSign::Zero))
    })
}

fn parallel_overlap_parameter_for_exact_cusp(
    map: &BezierAlgebraicCuspSemicircleParallelParameterMap2,
    parameter: &Real,
    range: &BezierParameterRange2,
    map_reversed: bool,
    policy: &CurveContext,
) -> CurveResult<Classification<BezierParameter2>> {
    let map = &map.data;
    let BezierParameter2::Algebraic(cusp_parameter) = &map.cusp_parameter else {
        return Err(CurveError::Topology(
            "cusp/parallel map lost its retained cusp root".into(),
        ));
    };
    let one_minus = Real::one() - parameter;
    let denominator = &one_minus * &one_minus + parameter * parameter;
    match real_sign(&denominator, policy) {
        Some(RealSign::Positive) => {}
        Some(RealSign::Zero | RealSign::Negative) => {
            return Err(CurveError::Topology(
                "semicircle inverse-map denominator was not positive".into(),
            ));
        }
        None => return Ok(Classification::Uncertain(UncertaintyReason::RealSign)),
    }
    let radial_coefficient = Real::one() - Real::from(2_i8) * parameter;
    let predicate = BezierAlgebraicCuspTwoTermExpression2 {
        rational: bivariate_scaled_difference(
            &map.diameter_side.rational,
            &denominator,
            &map.radius_squared_denominator,
            &radial_coefficient,
        ),
        radical: bivariate_scale(map.diameter_side.radical.clone(), &denominator),
    };
    let incidence = bivariate_subtract(
        &bivariate_multiply(
            &bivariate_multiply(&predicate.rational, &predicate.rational),
            &map.speed_squared,
        ),
        &bivariate_multiply(&predicate.radical, &predicate.radical),
    );
    let incidence = match reduce_algebraic_cusp_bivariate(incidence, cusp_parameter, policy)? {
        Classification::Decided(incidence) => incidence,
        Classification::Uncertain(reason) => {
            return Ok(Classification::Uncertain(reason));
        }
    };
    let cusp_root = parameter_representation(cusp_parameter, policy);
    let quotient = algebraic_cusp_quotient_ring_fiber_projection(&incidence, &cusp_root, policy)?;
    // The quotient norm includes candidates contributed by conjugate cusp
    // roots. The unsquared replay below evaluates every candidate at the
    // selected cusp root, so it rejects both those foreign candidates and
    // the opposite radical branch in one exact predicate. Running the
    // general selected-fiber membership pass first would duplicate that
    // proof and can dominate reversal-heavy clipping.
    let candidates = match quotient {
        Classification::Decided(ResultantParameterProjection::Empty) => Vec::new(),
        Classification::Decided(ResultantParameterProjection::Parameters(candidates)) => candidates,
        Classification::Decided(ResultantParameterProjection::Degenerate)
        | Classification::Uncertain(_) => {
            match algebraic_cusp_projected_fiber_parameters(&incidence, cusp_parameter, policy)? {
                Classification::Decided(BezierAlgebraicCuspFiberProjection2::Parameters(
                    candidates,
                )) => candidates,
                Classification::Decided(
                    BezierAlgebraicCuspFiberProjection2::IdenticallyZero
                    | BezierAlgebraicCuspFiberProjection2::Degenerate,
                ) => return Ok(Classification::Uncertain(UncertaintyReason::Unsupported)),
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }
    };
    retain_unique_overlap_parameter(
        candidates,
        range,
        map_reversed,
        true,
        policy,
        |map_parameter| {
            algebraic_cusp_correlated_radical_sum_sign(
                &incidence,
                &predicate,
                &map.speed_squared,
                &map.cusp_parameter,
                map_parameter,
                policy,
            )
        },
    )
}

fn rational_mapped_cusp_represented_rational(
    map: &BezierAlgebraicCuspSemicircleRationalParameterMap2,
    contact: &BezierAlgebraicCuspSemicircleRationalMapContact2,
    policy: &CurveContext,
) -> CurveResult<Classification<Option<Real>>> {
    if let Some((_, value)) = map
        .data
        .represented_rational_values
        .lock()
        .expect("cusp/rational value cache mutex poisoned")
        .iter()
        .find(|(parameter, _)| parameter == &contact.other_parameter)
    {
        return Ok(Classification::Decided(value.clone()));
    }
    let other_parameter = match contact
        .other_parameter
        .clone()
        .promote_represented_rational_root(policy)?
    {
        Classification::Decided(BezierParameter2::Exact(parameter)) => parameter,
        Classification::Decided(BezierParameter2::Algebraic(_)) => {
            return Ok(Classification::Decided(None));
        }
        Classification::Uncertain(reason) => {
            return Ok(Classification::Uncertain(reason));
        }
    };
    let diameter_side = bivariate_exact_second_fiber(&map.data.diameter_side, &other_parameter);
    let radius_squared_denominator =
        bivariate_exact_second_fiber(&map.data.radius_squared_denominator, &other_parameter);
    let incidence = bivariate_subtract(
        &bivariate_tensor_product(
            &diameter_side,
            &[Real::one(), Real::from(-2_i8), Real::from(2_i8)],
        ),
        &bivariate_tensor_product(
            &radius_squared_denominator,
            &[Real::one(), Real::from(-2_i8)],
        ),
    );
    let result = mapped_cusp_represented_rational_from_incidence(
        incidence,
        &map.data.cusp_parameter,
        policy,
        |parameter| map.mapped_contact_order_to_real(contact, parameter),
    )?;
    if let Classification::Decided(value) = &result {
        map.data
            .represented_rational_values
            .lock()
            .expect("cusp/rational value cache mutex poisoned")
            .push((contact.other_parameter.clone(), value.clone()));
    }
    Ok(result)
}

fn parallel_mapped_cusp_represented_rational(
    map: &BezierAlgebraicCuspSemicircleParallelParameterMap2,
    contact: &BezierAlgebraicCuspSemicircleParallelContact2,
    policy: &CurveContext,
) -> CurveResult<Classification<Option<Real>>> {
    if let Some((_, value)) = map
        .data
        .represented_rational_values
        .lock()
        .expect("cusp/parallel value cache mutex poisoned")
        .iter()
        .find(|(parameter, _)| parameter == &contact.parallel_parameter)
    {
        return Ok(Classification::Decided(value.clone()));
    }
    let other_parameter = match contact
        .parallel_parameter
        .clone()
        .promote_represented_rational_root(policy)?
    {
        Classification::Decided(BezierParameter2::Exact(parameter)) => parameter,
        Classification::Decided(BezierParameter2::Algebraic(_)) => {
            return Ok(Classification::Decided(None));
        }
        Classification::Uncertain(reason) => {
            return Ok(Classification::Uncertain(reason));
        }
    };
    let diameter_rational =
        bivariate_exact_second_fiber(&map.data.diameter_side.rational, &other_parameter);
    let diameter_radical =
        bivariate_exact_second_fiber(&map.data.diameter_side.radical, &other_parameter);
    let radius_squared_denominator =
        bivariate_exact_second_fiber(&map.data.radius_squared_denominator, &other_parameter);
    let speed_squared = bivariate_exact_second_fiber(&map.data.speed_squared, &other_parameter);
    let denominator = [Real::one(), Real::from(-2_i8), Real::from(2_i8)];
    let rational = bivariate_subtract(
        &bivariate_tensor_product(&diameter_rational, &denominator),
        &bivariate_tensor_product(
            &radius_squared_denominator,
            &[Real::one(), Real::from(-2_i8)],
        ),
    );
    let radical = bivariate_tensor_product(&diameter_radical, &denominator);
    let incidence = bivariate_subtract(
        &bivariate_multiply(
            &bivariate_multiply(&rational, &rational),
            &bivariate_tensor_product(&speed_squared, &[Real::one()]),
        ),
        &bivariate_multiply(&radical, &radical),
    );
    let result = mapped_cusp_represented_rational_from_incidence(
        incidence,
        &map.data.cusp_parameter,
        policy,
        |parameter| map.contact_order_to_real(contact, parameter),
    )?;
    if let Classification::Decided(value) = &result {
        map.data
            .represented_rational_values
            .lock()
            .expect("cusp/parallel value cache mutex poisoned")
            .push((contact.parallel_parameter.clone(), value.clone()));
    }
    Ok(result)
}

fn mapped_cusp_represented_rational_from_incidence(
    incidence: BivariatePolynomial,
    cusp_parameter: &BezierParameter2,
    policy: &CurveContext,
    mut order_to_real: impl FnMut(&Real) -> CurveResult<Classification<std::cmp::Ordering>>,
) -> CurveResult<Classification<Option<Real>>> {
    let BezierParameter2::Algebraic(cusp_parameter) = cusp_parameter else {
        return Ok(Classification::Decided(None));
    };
    let incidence = match reduce_algebraic_cusp_bivariate(incidence, cusp_parameter, policy)? {
        Classification::Decided(incidence) => incidence,
        Classification::Uncertain(reason) => {
            return Ok(Classification::Uncertain(reason));
        }
    };
    let candidates =
        match algebraic_cusp_reduced_fiber_parameters(&incidence, cusp_parameter, policy)? {
            Classification::Decided(BezierAlgebraicCuspFiberProjection2::Parameters(
                candidates,
            )) => candidates,
            Classification::Decided(
                BezierAlgebraicCuspFiberProjection2::IdenticallyZero
                | BezierAlgebraicCuspFiberProjection2::Degenerate,
            ) => return Ok(Classification::Decided(None)),
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
    let mut retained = None;
    for candidate in candidates {
        let candidate = match candidate.promote_represented_rational_root(policy)? {
            Classification::Decided(BezierParameter2::Exact(candidate)) => candidate,
            Classification::Decided(BezierParameter2::Algebraic(_)) => continue,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        match order_to_real(&candidate)? {
            Classification::Decided(std::cmp::Ordering::Equal) if retained.is_none() => {
                retained = Some(candidate);
            }
            Classification::Decided(std::cmp::Ordering::Equal) => {
                return Err(CurveError::Topology(
                    "mapped cusp cut had multiple exact rational values".into(),
                ));
            }
            Classification::Decided(std::cmp::Ordering::Less | std::cmp::Ordering::Greater) => {}
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        }
    }
    Ok(Classification::Decided(retained))
}

/// Tests same and complemented native parameters by the original unsquared
/// diameter coordinate. This is a per-cut proof: an isolated equality is
/// sufficient and cannot be mistaken for a global map equivalence.
fn rational_parallel_parameter_orientation_at_cut(
    rational: &BezierAlgebraicCuspSemicircleRationalParameterMap2,
    parallel: &BezierAlgebraicCuspSemicircleParallelParameterMap2,
    source_parameter: &BezierParameter2,
    source_is_rational: bool,
    policy: &CurveContext,
) -> CurveResult<Classification<Option<RationalBezierOverlapOrientation2>>> {
    if rational.data.policy != *policy || parallel.data.policy != *policy {
        return Err(CurveError::Topology(
            "cross-map cusp parameterization comparison used a different predicate policy".into(),
        ));
    }
    match rational
        .data
        .cusp_parameter
        .same_value(&parallel.data.cusp_parameter, policy)?
    {
        Classification::Decided(true) => {}
        Classification::Decided(false) => return Ok(Classification::Decided(None)),
        Classification::Uncertain(reason) => {
            return Ok(Classification::Uncertain(reason));
        }
    }
    let mut uncertain = None;
    for orientation in [
        RationalBezierOverlapOrientation2::Same,
        RationalBezierOverlapOrientation2::Reversed,
    ] {
        let rational_parameter =
            if source_is_rational || orientation == RationalBezierOverlapOrientation2::Same {
                source_parameter.clone()
            } else {
                source_parameter.unit_complement()
            };
        match rational_parallel_parameters_match_at_cut(
            rational,
            parallel,
            &rational_parameter,
            orientation,
            policy,
        )? {
            Classification::Decided(true) => {
                return Ok(Classification::Decided(Some(orientation)));
            }
            Classification::Decided(false) => {}
            Classification::Uncertain(reason) => uncertain = Some(reason),
        }
    }
    Ok(uncertain.map_or(Classification::Decided(None), Classification::Uncertain))
}

fn rational_parallel_parameters_match_at_cut(
    rational: &BezierAlgebraicCuspSemicircleRationalParameterMap2,
    parallel: &BezierAlgebraicCuspSemicircleParallelParameterMap2,
    rational_parameter: &BezierParameter2,
    orientation: RationalBezierOverlapOrientation2,
    policy: &CurveContext,
) -> CurveResult<Classification<bool>> {
    let orient = |polynomial: &BivariatePolynomial| {
        if orientation == RationalBezierOverlapOrientation2::Same {
            polynomial.clone()
        } else {
            bivariate_complement_second_parameter(polynomial)
        }
    };
    let parallel_diameter_rational = orient(&parallel.data.diameter_side.rational);
    let parallel_diameter_radical = orient(&parallel.data.diameter_side.radical);
    let parallel_radius_squared_denominator = orient(&parallel.data.radius_squared_denominator);
    let parallel_speed_squared = orient(&parallel.data.speed_squared);

    let rational_term = bivariate_subtract(
        &bivariate_multiply(
            &parallel_diameter_rational,
            &rational.data.radius_squared_denominator,
        ),
        &bivariate_multiply(
            &rational.data.diameter_side,
            &parallel_radius_squared_denominator,
        ),
    );
    let radical_term = bivariate_multiply(
        &parallel_diameter_radical,
        &rational.data.radius_squared_denominator,
    );
    let expression = BezierAlgebraicCuspTwoTermExpression2 {
        rational: rational_term,
        radical: radical_term,
    };
    Ok(
        match algebraic_cusp_independent_radical_sum_sign(
            &expression,
            &parallel_speed_squared,
            &rational.data.cusp_parameter,
            rational_parameter,
            policy,
        )? {
            Classification::Decided(RealSign::Zero) => Classification::Decided(true),
            Classification::Decided(RealSign::Positive | RealSign::Negative) => {
                Classification::Decided(false)
            }
            Classification::Uncertain(reason) => Classification::Uncertain(reason),
        },
    )
}

fn bivariate_complement_second_parameter(polynomial: &BivariatePolynomial) -> BivariatePolynomial {
    let degree = polynomial
        .coefficients
        .iter()
        .map(|row| row.len().saturating_sub(1))
        .max()
        .unwrap_or(0);
    let mut complement_powers = Vec::with_capacity(degree + 1);
    complement_powers.push(vec![Real::one()]);
    for power in 1..=degree {
        complement_powers.push(polynomial_multiply(
            &complement_powers[power - 1],
            &[Real::one(), Real::from(-1_i8)],
        ));
    }
    BivariatePolynomial::new(
        polynomial
            .coefficients
            .iter()
            .map(|row| {
                let mut complemented = vec![Real::zero(); row.len()];
                for (source_power, coefficient) in row.iter().enumerate() {
                    for (target_power, factor) in complement_powers[source_power].iter().enumerate()
                    {
                        complemented[target_power] += coefficient * factor;
                    }
                }
                complemented
            })
            .collect(),
    )
}

fn bivariate_exact_second_fiber(polynomial: &BivariatePolynomial, parameter: &Real) -> Vec<Real> {
    polynomial
        .coefficients
        .iter()
        .map(|row| {
            row.iter().rev().fold(Real::zero(), |value, coefficient| {
                value * parameter + coefficient
            })
        })
        .collect()
}

fn bivariate_tensor_product(first: &[Real], second: &[Real]) -> BivariatePolynomial {
    BivariatePolynomial::new(
        first
            .iter()
            .map(|first| second.iter().map(|second| first * second).collect())
            .collect(),
    )
}

fn retain_unique_overlap_parameter<F>(
    candidates: Vec<BezierParameter2>,
    range: &BezierParameterRange2,
    map_reversed: bool,
    include_boundaries: bool,
    policy: &CurveContext,
    mut predicate_sign: F,
) -> CurveResult<Classification<BezierParameter2>>
where
    F: FnMut(&BezierParameter2) -> CurveResult<Classification<RealSign>>,
{
    let mut retained = None;
    for map_parameter in candidates {
        let sign = match predicate_sign(&map_parameter)? {
            Classification::Decided(sign) => sign,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        if sign != RealSign::Zero {
            continue;
        }
        let candidate = if map_reversed {
            map_parameter.unit_complement()
        } else {
            map_parameter
        };
        let in_range =
            match overlap_parameter_is_in_range(&candidate, range, include_boundaries, policy)? {
                Classification::Decided(in_range) => in_range,
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            };
        if in_range && retained.replace(candidate).is_some() {
            return Err(CurveError::Topology(
                "one cusp cut mapped to multiple parameters in one regular overlap cell".into(),
            ));
        }
    }
    match retained {
        Some(parameter) => Ok(Classification::Decided(parameter)),
        None => Err(CurveError::Topology(
            "cusp cut had no parameter on its published mapped overlap".into(),
        )),
    }
}

fn retain_direct_overlap_parameter(
    parameter: BezierParameter2,
    range: &BezierParameterRange2,
    policy: &CurveContext,
) -> CurveResult<Classification<BezierParameter2>> {
    match overlap_parameter_is_in_range(&parameter, range, true, policy)? {
        Classification::Decided(true) => Ok(Classification::Decided(parameter)),
        Classification::Decided(false) => Err(CurveError::Topology(
            "cusp cut had no parameter on its published mapped overlap".into(),
        )),
        Classification::Uncertain(reason) => Ok(Classification::Uncertain(reason)),
    }
}

fn overlap_parameter_is_in_range(
    parameter: &BezierParameter2,
    range: &BezierParameterRange2,
    include_boundaries: bool,
    policy: &CurveContext,
) -> CurveResult<Classification<bool>> {
    let after_start = match parameter.cmp_by_refinement(range.start(), policy)? {
        Classification::Decided(std::cmp::Ordering::Less) => false,
        Classification::Decided(std::cmp::Ordering::Equal) => include_boundaries,
        Classification::Decided(std::cmp::Ordering::Greater) => true,
        Classification::Uncertain(reason) => return Ok(Classification::Uncertain(reason)),
    };
    let before_end = match parameter.cmp_by_refinement(range.end(), policy)? {
        Classification::Decided(std::cmp::Ordering::Greater) => false,
        Classification::Decided(std::cmp::Ordering::Equal) => include_boundaries,
        Classification::Decided(std::cmp::Ordering::Less) => true,
        Classification::Uncertain(reason) => return Ok(Classification::Uncertain(reason)),
    };
    Ok(Classification::Decided(after_start && before_end))
}

fn mapped_overlap_parameters_for_exact_cusp(
    overlaps: Vec<BezierAlgebraicCuspSemicircleMappedOverlap2>,
    parameter: &Real,
    policy: &CurveContext,
) -> CurveResult<Classification<Vec<BezierParameter2>>> {
    let parameter = BezierAlgebraicCuspSemicircleParameter2::Exact(parameter.clone());
    let mut candidates: Vec<BezierParameter2> = Vec::new();
    for overlap in overlaps {
        let after_start = match parameter.cmp_by_refinement(&overlap.cusp_start, policy)? {
            Classification::Decided(std::cmp::Ordering::Less) => false,
            Classification::Decided(std::cmp::Ordering::Equal | std::cmp::Ordering::Greater) => {
                true
            }
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let before_end = match parameter.cmp_by_refinement(&overlap.cusp_end, policy)? {
            Classification::Decided(std::cmp::Ordering::Greater) => false,
            Classification::Decided(std::cmp::Ordering::Equal | std::cmp::Ordering::Less) => true,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        if !after_start || !before_end {
            continue;
        }
        let candidate = match overlap.other_parameter_for_cusp(&parameter, policy)? {
            Classification::Decided(candidate) => candidate,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let mut duplicate = false;
        for existing in &candidates {
            match existing.same_value(&candidate, policy)? {
                Classification::Decided(true) => {
                    duplicate = true;
                    break;
                }
                Classification::Decided(false) => {}
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }
        if !duplicate {
            candidates.push(candidate);
        }
    }
    Ok(Classification::Decided(candidates))
}

fn rational_parameters_for_cusp_endpoint(
    source: &BezierAlgebraicCuspSemicircle2,
    parameter: &Real,
    target: &RationalBezier2,
    policy: &CurveContext,
) -> CurveResult<Classification<Vec<BezierParameter2>>> {
    match source.rational_intersections(target, policy)? {
        Classification::Decided(BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(
            overlaps,
        )) => mapped_overlap_parameters_for_exact_cusp(overlaps, parameter, policy),
        Classification::Decided(
            BezierAlgebraicCuspSemicircleRationalIntersections2::DegenerateProjection,
        ) => Ok(Classification::Uncertain(UncertaintyReason::Unsupported)),
        Classification::Decided(BezierAlgebraicCuspSemicircleRationalIntersections2::Contacts(
            _,
        )) => Err(CurveError::Topology(
            "a coincident cusp endpoint replayed against a noncoincident rational carrier".into(),
        )),
        Classification::Uncertain(reason) => Ok(Classification::Uncertain(reason)),
    }
}

fn parallel_parameters_for_cusp_endpoint(
    source: &BezierAlgebraicCuspSemicircle2,
    parameter: &Real,
    target: &BezierParallel2,
    policy: &CurveContext,
) -> CurveResult<Classification<Vec<BezierParameter2>>> {
    match source.parallel_intersections(target, policy)? {
        Classification::Decided(BezierAlgebraicCuspSemicircleParallelIntersections2::Overlaps(
            overlaps,
        )) => mapped_overlap_parameters_for_exact_cusp(overlaps, parameter, policy),
        Classification::Decided(
            BezierAlgebraicCuspSemicircleParallelIntersections2::DegenerateProjection,
        ) => Ok(Classification::Uncertain(UncertaintyReason::Unsupported)),
        Classification::Decided(BezierAlgebraicCuspSemicircleParallelIntersections2::Contacts(
            _,
        )) => Err(CurveError::Topology(
            "a coincident cusp endpoint replayed against a noncoincident analytic carrier".into(),
        )),
        Classification::Uncertain(reason) => Ok(Classification::Uncertain(reason)),
    }
}

/// Maps one interior point between exact carriers of the same selected circle
/// by their tangent line. On a circle, a tangent line identifies only the
/// point and its antipode; one published semicircle overlap range contains at
/// most one of those interior points.
fn mapped_circle_tangent_parameter_candidates(
    source_parameter: &BezierParameter2,
    source_tangent: &[Vec<Real>; 2],
    target_tangent: &[Vec<Real>; 2],
    policy: &CurveContext,
) -> CurveResult<Classification<Vec<BezierParameter2>>> {
    let incidence = bivariate_subtract(
        &bivariate_outer_product(&source_tangent[0], &target_tangent[1]),
        &bivariate_outer_product(&source_tangent[1], &target_tangent[0]),
    );
    let candidates = match source_parameter {
        BezierParameter2::Exact(parameter) => {
            let coefficients = bivariate_specialize_first(&incidence, parameter);
            let mut nonzero = false;
            for coefficient in &coefficients {
                match real_sign(coefficient, policy) {
                    Some(RealSign::Positive | RealSign::Negative) => nonzero = true,
                    Some(RealSign::Zero) => {}
                    None => {
                        return Ok(Classification::Uncertain(UncertaintyReason::RealSign));
                    }
                }
            }
            if !nonzero {
                return Ok(Classification::Uncertain(UncertaintyReason::Unsupported));
            }
            let polynomial = match polynomial_from_coefficients(coefficients, policy)? {
                Classification::Decided(Some(polynomial)) => polynomial,
                Classification::Decided(None) => {
                    return Err(CurveError::Topology(
                        "nonzero tangent correspondence had no parameter polynomial".into(),
                    ));
                }
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            };
            polynomial.isolate_unit_interval_roots(policy)?
        }
        BezierParameter2::Algebraic(parameter) => {
            match algebraic_cusp_projected_fiber_parameters(&incidence, parameter, policy)? {
                Classification::Decided(BezierAlgebraicCuspFiberProjection2::Parameters(
                    parameters,
                )) => Classification::Decided(parameters),
                Classification::Decided(
                    BezierAlgebraicCuspFiberProjection2::IdenticallyZero
                    | BezierAlgebraicCuspFiberProjection2::Degenerate,
                ) => Classification::Uncertain(UncertaintyReason::Unsupported),
                Classification::Uncertain(reason) => Classification::Uncertain(reason),
            }
        }
    };
    Ok(candidates)
}

