    #[cfg(feature = "predicates")]
    fn synthetic_selected_cusp_semicircle(
        source_x_numerator: Vec<Real>,
        root_square: Real,
        lower: Real,
        upper: Real,
        radial_distance: Real,
        policy: &CurveContext,
    ) -> BezierAlgebraicCuspSemicircle2 {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-root_square, Real::zero(), Real::one()],
            policy,
        )
        .unwrap() else {
            panic!("independent cusp polynomial must be exact");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(lower, upper, policy).unwrap()
        else {
            panic!("independent cusp interval must be exact");
        };
        let Classification::Decided(parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, policy).unwrap()
        else {
            panic!("independent cusp root must isolate");
        };
        let source = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::zero(), Real::zero()),
                Point2::new(Real::one(), Real::zero()),
            )
            .unwrap(),
        );
        BezierAlgebraicCuspSemicircle2 {
            data: Arc::new(BezierAlgebraicCuspSemicircleData2 {
                frame: BezierParallelAlgebraicCuspFrame2 {
                    data: Arc::new(BezierParallelAlgebraicCuspFrameData2 {
                        parallel: source.parallel_left(Real::zero()).unwrap(),
                        parameter,
                        source_x_numerator,
                        source_y_numerator: vec![Real::zero()],
                        normal_x_numerator: vec![Real::one()],
                        normal_y_numerator: vec![Real::zero()],
                        denominator: vec![Real::one()],
                    }),
                },
                radial_distance,
                clockwise: false,
            }),
        }
    }

    #[cfg(feature = "predicates")]
    fn synthetic_reducible_cusp_semicircle(
        selected_root: (i64, i64),
        interval: ((i64, i64), (i64, i64)),
        policy: &CurveContext,
    ) -> BezierAlgebraicCuspSemicircle2 {
        // P(a)=(a-1/4)(a-3/4). The retained frame center is
        // 10(a-3/4), so the foreign root a=3/4 owns the unit circle at the
        // origin while the selected a=1/4 circle is centered at (-5,0).
        let rational = |numerator: i64, denominator: i64| {
            (Real::from(numerator) / Real::from(denominator)).unwrap()
        };
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![rational(3, 16), Real::from(-1_i8), Real::one()],
            policy,
        )
        .unwrap() else {
            panic!("reducible cusp polynomial must be exact");
        };
        let Classification::Decided(interval) = BezierParameterInterval::try_new(
            rational(interval.0.0, interval.0.1),
            rational(interval.1.0, interval.1.1),
            policy,
        )
        .unwrap() else {
            panic!("selected cusp interval must be exact");
        };
        let Classification::Decided(parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, policy).unwrap()
        else {
            panic!("selected cusp root must isolate");
        };
        let selected = rational(selected_root.0, selected_root.1);
        assert_eq!(parameter.polynomial().evaluate(&selected), Real::zero());

        let source = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::from(-5_i8), Real::zero()),
                Point2::new(Real::zero(), Real::zero()),
            )
            .unwrap(),
        );
        let parallel = source.parallel_left(Real::zero()).unwrap();
        BezierAlgebraicCuspSemicircle2 {
            data: Arc::new(BezierAlgebraicCuspSemicircleData2 {
                frame: BezierParallelAlgebraicCuspFrame2 {
                    data: Arc::new(BezierParallelAlgebraicCuspFrameData2 {
                        parallel,
                        parameter,
                        source_x_numerator: vec![rational(-15, 2), Real::from(10_i8)],
                        source_y_numerator: vec![Real::zero()],
                        normal_x_numerator: vec![Real::one()],
                        normal_y_numerator: vec![Real::zero()],
                        denominator: vec![Real::one()],
                    }),
                },
                radial_distance: Real::one(),
                clockwise: false,
            }),
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn curve_region_retains_and_classifies_an_algebraic_cusp_semicircle() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let semicircle = synthetic_reducible_cusp_semicircle((3, 4), ((2, 3), (4, 5)), &policy);
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            let center = semicircle
                .center_point_image(&policy)
                .unwrap()
                .exact_rational_point(&policy)
                .expect("the synthetic rational cusp center must materialize exactly");
            let Classification::Decided(boundary_point) =
                semicircle.point_at(&half, &policy).unwrap()
            else {
                panic!("the synthetic rational cusp midpoint must complete");
            };
            let boundary_point = boundary_point
                .exact_rational_point(&policy)
                .expect("the synthetic rational cusp midpoint must materialize exactly");
            let cusp = crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                BezierAlgebraicCuspSemicircleFragment2::full(semicircle, &policy),
            );
            let crate::BezierSplitFragment2::AlgebraicCuspSemicircle(fragment) = &cusp else {
                unreachable!();
            };
            let start = fragment
                .endpoint_exact_point(true, &policy)
                .unwrap()
                .expect("the synthetic rational cusp start must materialize exactly");
            let end = fragment
                .endpoint_exact_point(false, &policy)
                .unwrap()
                .expect("the synthetic rational cusp end must materialize exactly");
            let diameter = crate::BezierSplitFragment2::Materialized {
                start: BezierParameter2::Exact(Real::zero()),
                end: BezierParameter2::Exact(Real::one()),
                curve: crate::BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
                    LineSeg2::try_new(end, start).unwrap(),
                )),
            };
            let boundary = crate::CurveRegionBoundaryLoop2::new(vec![cusp, diameter], &policy)
                .expect("rational cusp endpoints must connect to the exact diameter");
            let region = crate::CurveRegion2::new(vec![boundary]).unwrap();
            let radial_x = boundary_point.x() - center.x();
            let radial_y = boundary_point.y() - center.y();
            let inside = Point2::new(
                center.x() + (&radial_x * &half),
                center.y() + (&radial_y * &half),
            );
            let outside = Point2::new(
                center.x() - (&radial_x * &half),
                center.y() - (&radial_y * &half),
            );
            assert_eq!(
                region
                    .classify_point(&inside, &policy)
                    .map(crate::CurveOutcome::into_value),
                Ok(Classification::Decided(crate::RegionPointLocation::Inside)),
            );
            assert_eq!(
                region
                    .classify_point(&outside, &policy)
                    .map(crate::CurveOutcome::into_value),
                Ok(Classification::Decided(crate::RegionPointLocation::Outside)),
            );
            assert_eq!(
                region
                    .classify_point(&boundary_point, &policy)
                    .map(crate::CurveOutcome::into_value),
                Ok(Classification::Decided(
                    crate::RegionPointLocation::Boundary
                )),
            );
            assert!(region.has_algebraic_fragments());
            let regularized = region
                .regularized_region(&policy)
                .expect("the retained cusp/diameter loop must regularize")
                .into_value();
            assert_eq!(
                regularized
                    .classify_point(&inside, &policy)
                    .map(crate::CurveOutcome::into_value),
                Ok(Classification::Decided(crate::RegionPointLocation::Inside)),
            );
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn curve_region_boolean_clips_correlated_partial_cusp_overlaps() {
        let quarter_turn_to_origin = Similarity2::try_from_real_affine(
            Real::zero(),
            Real::from(-1_i8),
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::from(5_i8),
        )
        .unwrap();
        let rational =
            |numerator, denominator| (Real::from(numerator) / Real::from(denominator)).unwrap();
        let first_start = rational(3, 5);
        let first_end = rational(4, 5);
        let second_start = rational(1, 4);
        let second_end = rational(1, 2);
        let expected = [
            rational(2, 3),
            first_end.clone(),
            second_start.clone(),
            rational(3, 8),
        ];

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = synthetic_reducible_cusp_semicircle((3, 4), ((2, 3), (4, 5)), &policy);
            let second = synthetic_reducible_cusp_semicircle((1, 4), ((1, 5), (1, 3)), &policy)
                .transform_similarity(&quarter_turn_to_origin)
                .unwrap();
            let segment_region = |semicircle: BezierAlgebraicCuspSemicircle2,
                                  start: Real,
                                  end: Real| {
                let Classification::Decided(fragment) =
                    BezierAlgebraicCuspSemicircleFragment2::try_new(
                        semicircle,
                        BezierAlgebraicCuspSemicircleParameter2::Exact(start),
                        BezierAlgebraicCuspSemicircleParameter2::Exact(end),
                        false,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the represented circular-segment arc must be ordered");
                };
                let arc = crate::BezierSplitFragment2::AlgebraicCuspSemicircle(fragment.clone());
                let start = fragment
                    .endpoint_exact_point(true, &policy)
                    .unwrap()
                    .expect("the synthetic segment start must be rational");
                let end = fragment
                    .endpoint_exact_point(false, &policy)
                    .unwrap()
                    .expect("the synthetic segment end must be rational");
                let chord = crate::BezierSplitFragment2::Materialized {
                    start: BezierParameter2::Exact(Real::zero()),
                    end: BezierParameter2::Exact(Real::one()),
                    curve: crate::BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
                        LineSeg2::try_new(end, start).unwrap(),
                    )),
                };
                crate::CurveRegion2::try_new_with_loop_topology(
                    vec![crate::CurveRegionBoundaryLoop2::new(vec![arc, chord], &policy).unwrap()],
                    vec![crate::CurveRegionLoopRole::Material],
                    vec![crate::FillRule::NonZero],
                    vec![crate::CurveBoundaryInteriorSide2::Left],
                )
                .unwrap()
            };
            let first_region = segment_region(first, first_start.clone(), first_end.clone());
            let second_region = segment_region(second, second_start.clone(), second_end.clone());

            let intersections = first_region
                .intersect_region(&second_region, &policy)
                .unwrap()
                .into_value();
            assert!(intersections.is_complete(), "{intersections:?}");
            let cusp_overlap = intersections
                .overlaps()
                .iter()
                .find(|overlap| overlap.first_range().start().is_algebraic_cusp())
                .unwrap_or_else(|| {
                    panic!(
                        "the correlated shared subarc must survive carrier clipping: {intersections:?}"
                    )
                });
            for (actual, expected) in [
                (cusp_overlap.first_range().start(), &expected[0]),
                (cusp_overlap.first_range().end(), &expected[1]),
                (cusp_overlap.second_range().start(), &expected[2]),
                (cusp_overlap.second_range().end(), &expected[3]),
            ] {
                assert_eq!(
                    actual
                        .as_algebraic_cusp()
                        .expect("the shared subarc must retain cusp parameters")
                        .order_to_real(expected, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }

            let booleans = first_region
                .boolean_regions(&second_region, &policy)
                .unwrap()
                .into_value();
            assert!(!booleans.intersection().is_empty());
            assert!(booleans.intersection().has_algebraic_fragments());
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn simple_general_algebraic_cusp_loop_regularizes_without_materializing_its_field() {
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let (_parallel, source_parameter, semicircle) =
                general_algebraic_cusp_semicircle(quarter.clone(), false, &policy);
            let cusp_fragment =
                BezierAlgebraicCuspSemicircleFragment2::full(semicircle.clone(), &policy);
            let Classification::Decided(representative) =
                cusp_fragment.representative_point().unwrap()
            else {
                panic!("the general cusp representative expression must be retained");
            };
            assert!(
                representative.exact_rational_point(&policy).is_none(),
                "the topology proof must not depend on a rationalized cusp field"
            );

            let source_parameter = BezierParameter2::Algebraic(source_parameter);
            let start_parallel = semicircle.start_parallel();
            let end_parallel = semicircle.end_parallel();
            let local_start = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
            let regular_span = |parallel: &BezierParallel2| {
                let range = match BezierParameterRange2::try_new(
                    BezierParameter2::Exact(local_start.clone()),
                    source_parameter.clone(),
                    &policy,
                )
                .unwrap()
                {
                    Classification::Decided(range) => range,
                    Classification::Uncertain(reason) => panic!("local cusp range: {reason:?}"),
                };
                match crate::BezierParallelFragment2::try_new(parallel.clone(), range, &policy)
                    .unwrap()
                {
                    Classification::Decided(fragment) => fragment,
                    Classification::Uncertain(reason) => {
                        panic!("regular local cusp span: {reason:?}")
                    }
                }
            };
            let start_fragment = regular_span(&start_parallel);
            let end_fragment = regular_span(&end_parallel);
            for (parallel, fragment, expected_location) in [
                (
                    &start_parallel,
                    &start_fragment,
                    BezierAlgebraicCuspSemicircleContactLocation2::Start,
                ),
                (
                    &end_parallel,
                    &end_fragment,
                    BezierAlgebraicCuspSemicircleContactLocation2::End,
                ),
            ] {
                let classified = semicircle
                    .parallel_intersections_in_range(parallel, fragment.range(), &policy)
                    .unwrap();
                let Classification::Decided(intersections) = classified else {
                    panic!(
                        "adjacent cusp/parallel range intersection at {expected_location:?} must decide: {classified:?}"
                    );
                };
                let BezierAlgebraicCuspSemicircleParallelIntersections2::Contacts(contacts) =
                    intersections
                else {
                    panic!("adjacent cusp/parallel range intersection: {intersections:?}");
                };
                assert!(
                    contacts.iter().any(|contact| {
                        contact.location == expected_location
                            && contact
                                .parallel_parameter
                                .same_value(&source_parameter, &policy)
                                == Ok(Classification::Decided(true))
                    }),
                    "adjacent contacts: {contacts:?}"
                );
            }
            let reversed_start = start_parallel.reversed();
            let reversed_range = BezierParameterRange2::new_validated(
                start_fragment.range().end().unit_complement(),
                start_fragment.range().start().unit_complement(),
            );
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::Contacts(contacts),
            ) = semicircle
                .parallel_intersections_in_range(&reversed_start, &reversed_range, &policy)
                .unwrap()
            else {
                panic!("reversed adjacent cusp/parallel range intersection must decide");
            };
            let reversed_source_parameter = source_parameter.unit_complement();
            assert!(contacts.iter().any(|contact| {
                contact.location == BezierAlgebraicCuspSemicircleContactLocation2::Start
                    && contact.tangent_cross_sign == Some(RealSign::Zero)
                    && contact
                        .parallel_parameter
                        .same_value(&reversed_source_parameter, &policy)
                        == Ok(Classification::Decided(true))
            }));
            let complement = BezierAlgebraicCuspSemicircle2 {
                data: Arc::new(BezierAlgebraicCuspSemicircleData2 {
                    frame: semicircle.data.frame.clone(),
                    radial_distance: -quarter.clone(),
                    clockwise: semicircle.is_clockwise(),
                }),
            };
            let Classification::Decided(
                BezierAlgebraicCuspSemicirclePairIntersections2::EndpointContacts(contacts),
            ) = semicircle.pair_intersections(&complement, &policy).unwrap()
            else {
                panic!("complementary general cusp halves must meet only at their endpoints");
            };
            assert_eq!(contacts.len(), 2);
            let fragments = vec![
                crate::BezierSplitFragment2::AlgebraicCuspSemicircle(cusp_fragment),
                crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(complement, &policy),
                ),
            ];
            let boundary = crate::CurveRegionBoundaryLoop2::new(fragments, &policy)
                .expect("the correlated cusp endpoints must close the authored loop");
            let region = crate::CurveRegion2::try_new_with_loop_topology(
                vec![boundary],
                vec![crate::CurveRegionLoopRole::Material],
                vec![crate::FillRule::NonZero],
                vec![crate::CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            let regularized = region
                .regularized_region(&policy)
                .expect("the simple general cusp topology must regularize")
                .into_value();
            assert_eq!(regularized.boundary_loops().len(), 1);
            assert!(
                regularized.boundary_loops()[0]
                    .fragments()
                    .iter()
                    .any(|fragment| matches!(
                        fragment,
                        crate::BezierSplitFragment2::AlgebraicCuspSemicircle(_)
                    ))
            );

            let corners = [
                Point2::from_values(-10, -10),
                Point2::from_values(10, -10),
                Point2::from_values(10, 10),
                Point2::from_values(-10, 10),
            ];
            let square = CurvePath2::try_new(
                (0..corners.len())
                    .map(|index| {
                        Curve2::from(
                            LineSeg2::try_new(
                                corners[index].clone(),
                                corners[(index + 1) % corners.len()].clone(),
                            )
                            .unwrap(),
                        )
                    })
                    .collect(),
            )
            .unwrap();
            let container = crate::CurveRegion2::try_from_boundary_paths(&[square], &policy)
                .unwrap()
                .into_value();
            let booleans = region
                .boolean_regions(&container, &policy)
                .expect("the all-algebraic cusp loop must classify against an affine region")
                .into_value();
            assert!(booleans.intersection().has_algebraic_fragments());
            assert!(booleans.difference().is_empty());
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn algebraic_cusp_disk_classifies_an_independent_selected_root_directly() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            // The circle center is alpha=sqrt(1/3). The query x-coordinate is
            // the independently selected beta=sqrt(1/2), so no rationalized
            // point or diagonal selected-root identity is available.
            let upper = synthetic_independent_unit_cusp_semicircle_with_center_x(
                vec![Real::zero(), Real::one()],
                &policy,
            );
            let lower = BezierAlgebraicCuspSemicircle2 {
                data: Arc::new(BezierAlgebraicCuspSemicircleData2 {
                    frame: upper.data.frame.clone(),
                    radial_distance: -Real::one(),
                    clockwise: false,
                }),
            };
            let boundary = crate::CurveRegionBoundaryLoop2::new(
                vec![
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(upper.clone(), &policy),
                    ),
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(lower, &policy),
                    ),
                ],
                &policy,
            )
            .expect("the two selected-field semicircles must close exactly");
            let region = crate::CurveRegion2::try_new_with_loop_topology(
                vec![boundary],
                vec![crate::CurveRegionLoopRole::Material],
                vec![crate::FillRule::NonZero],
                vec![crate::CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let BezierParameter2::Algebraic(query_parameter) =
                algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
            else {
                panic!("the independent query root must remain algebraic");
            };
            let query_line = |start: i8, end: i8| {
                RationalBezier2::try_from_subcurve(&crate::BezierSubcurve2::Quadratic(
                    QuadraticBezier2::from_line_segment(
                        LineSeg2::try_new(
                            Point2::from_values(start, 0),
                            Point2::from_values(end, 0),
                        )
                        .unwrap(),
                    ),
                ))
                .unwrap()
            };
            let inside = RationalBezierAlgebraicPointImage2::from_parametric_source(
                query_line(0, 1),
                query_parameter.clone(),
                &policy,
            );
            assert!(inside.exact_rational_point(&policy).is_none());
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&inside, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Inside),
            );

            let outside = RationalBezierAlgebraicPointImage2::from_parametric_source(
                query_line(2, 3),
                query_parameter,
                &policy,
            );
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&outside, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Outside),
            );

            let Classification::Decided(boundary) = upper.point_at(&half, &policy).unwrap() else {
                panic!("the selected-field boundary point must remain exact");
            };
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&boundary, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Boundary),
            );
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn distinct_mapped_algebraic_cusp_endpoint_fields_classify_directly() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let fifth = (Real::one() / Real::from(5_i8)).unwrap();
        let two_fifths = Real::from(2_i8) * &fifth;
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let upper = synthetic_reducible_cusp_semicircle((3, 4), ((2, 3), (4, 5)), &policy);
            let rational_quarter = RationalBezier2::from(
                RationalQuadraticBezier2::try_new(
                    Point2::new(Real::one(), Real::zero()),
                    Point2::new(Real::one(), Real::one()),
                    Point2::new(Real::zero(), Real::one()),
                    Real::one(),
                    Real::one(),
                    Real::from(2_i8),
                )
                .unwrap(),
            );
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(overlaps),
            ) = upper
                .rational_intersections(&rational_quarter, &policy)
                .unwrap()
            else {
                panic!("the rational quarter must publish its cusp correspondence");
            };
            let [overlap] = overlaps.as_slice() else {
                panic!("the rational quarter must retain one monotone overlap");
            };
            let mapped_cut = |root_square: Real| {
                let BezierParameter2::Algebraic(source) =
                    algebraic_parameter(vec![-root_square, Real::zero(), Real::one()])
                else {
                    panic!("the rational-carrier cut must remain algebraic");
                };
                let Classification::Decided(cut) = overlap
                    .cusp_parameter_for_other(&BezierParameter2::Algebraic(source.clone()), &policy)
                    .unwrap()
                else {
                    panic!("the algebraic rational-carrier cut must map to the cusp");
                };
                assert_eq!(
                    cut.represented_rational_value(&policy).unwrap(),
                    Classification::Decided(None),
                );
                (source, cut)
            };
            let (_, first_cut) = mapped_cut(third.clone());
            let (_, second_cut) = mapped_cut(half.clone());

            let Classification::Decided(first) = BezierAlgebraicCuspSemicircleFragment2::try_new(
                upper.clone(),
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                first_cut.clone(),
                false,
                &policy,
            )
            .unwrap() else {
                panic!("the mapped first cusp cell must be ordered");
            };
            let Classification::Decided(middle) = BezierAlgebraicCuspSemicircleFragment2::try_new(
                upper.clone(),
                first_cut,
                second_cut.clone(),
                false,
                &policy,
            )
            .unwrap() else {
                panic!("the distinct-field middle cusp cell must be ordered");
            };
            let Classification::Decided(last) = BezierAlgebraicCuspSemicircleFragment2::try_new(
                upper.clone(),
                second_cut,
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::one()),
                false,
                &policy,
            )
            .unwrap() else {
                panic!("the mapped last cusp cell must be ordered");
            };
            for fragment in [&first, &middle, &last] {
                assert!(matches!(
                    fragment.algebraic_ray_evaluator(&policy).unwrap(),
                    Classification::Decided(_)
                ));
            }
            let lower =
                BezierAlgebraicCuspSemicircleFragment2::full(upper.complementary_half(), &policy);
            let boundary = crate::CurveRegionBoundaryLoop2::new(
                vec![
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(first),
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(middle),
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(last),
                    crate::BezierSplitFragment2::AlgebraicCuspSemicircle(lower),
                ],
                &policy,
            )
            .expect("the mapped cusp cells must close one exact disk");
            let region = crate::CurveRegion2::try_new_with_loop_topology(
                vec![boundary],
                vec![crate::CurveRegionLoopRole::Material],
                vec![crate::FillRule::NonZero],
                vec![crate::CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let BezierParameter2::Algebraic(query_parameter) =
                algebraic_parameter(vec![-fifth.clone(), Real::zero(), Real::one()])
            else {
                panic!("the independent query must remain algebraic");
            };
            let query_line = |start: i8, end: i8| {
                RationalBezier2::try_from_subcurve(&crate::BezierSubcurve2::Quadratic(
                    QuadraticBezier2::from_line_segment(
                        LineSeg2::try_new(
                            Point2::from_values(start, 0),
                            Point2::from_values(end, 0),
                        )
                        .unwrap(),
                    ),
                ))
                .unwrap()
            };
            let inside = RationalBezierAlgebraicPointImage2::from_parametric_source(
                query_line(0, 1),
                query_parameter.clone(),
                &policy,
            );
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&inside, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Inside),
            );
            let outside = RationalBezierAlgebraicPointImage2::from_parametric_source(
                query_line(2, 3),
                query_parameter,
                &policy,
            );
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&outside, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Outside),
            );
            let BezierParameter2::Algebraic(boundary_parameter) =
                algebraic_parameter(vec![-two_fifths.clone(), Real::zero(), Real::one()])
            else {
                panic!("the middle-cell boundary query must remain algebraic");
            };
            let boundary = RationalBezierAlgebraicPointImage2::from_parametric_source(
                rational_quarter.clone(),
                boundary_parameter,
                &policy,
            );
            assert_eq!(
                region
                    .classify_algebraic_point_raw(&boundary, &policy)
                    .unwrap(),
                Classification::Decided(crate::RegionPointLocation::Boundary),
            );
        }
    }

    #[cfg(feature = "predicates")]
    fn independent_field_collinear_chord_side(
        root_coefficients: [Vec<Real>; 3],
        policy: &CurveContext,
    ) -> Classification<crate::classify::LineSide> {
        let points = root_coefficients
            .into_iter()
            .enumerate()
            .map(|(index, coefficients)| {
                let BezierParameter2::Algebraic(parameter) = algebraic_parameter(coefficients)
                else {
                    unreachable!("the selected related root must remain algebraic");
                };
                let (x, y) = match index {
                    0 => (vec![Real::zero(), Real::one()], vec![Real::zero()]),
                    1 => (vec![Real::zero()], vec![Real::zero(), Real::one()]),
                    2 => (
                        vec![Real::zero(), Real::one()],
                        vec![Real::zero(), Real::one()],
                    ),
                    _ => unreachable!(),
                };
                RationalBezierAlgebraicPointImage2::from_retained_expression(
                    parameter.clone(),
                    parameter_representation(&parameter, policy),
                    x,
                    y,
                    vec![Real::one()],
                    "test independent-field collinear point",
                )
            })
            .collect::<Vec<_>>();
        let predicates = points
            .iter()
            .map(|point| {
                let Classification::Decided(predicate) = point.predicate_evaluator(policy).unwrap()
                else {
                    panic!("the retained collinear point must expose its predicate");
                };
                predicate
            })
            .collect::<Vec<_>>();
        algebraic_point_oriented_line_side(&predicates[0], &predicates[1], &predicates[2], policy)
            .unwrap()
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn trivariate_affine_axis_substitution_preserves_all_axis_orders() {
        let polynomial = TrivariatePolynomial2 {
            coefficients: (0..3)
                .map(|first| {
                    (0..4)
                        .map(|second| {
                            (0..2)
                                .map(|third| Real::from(1_i32 + first * 7 + second * 3 + third * 5))
                                .collect()
                        })
                        .collect()
                })
                .collect(),
        };
        let scale = (Real::from(-3_i8) / Real::from(2_i8)).unwrap();
        let offset = (Real::from(7_i8) / Real::from(11_i8)).unwrap();
        let retained_value = (Real::from(2_i8) / Real::from(5_i8)).unwrap();
        let remaining_value = (Real::from(4_i8) / Real::from(7_i8)).unwrap();
        let evaluate_trivariate = |values: &[Real; 3]| {
            polynomial
                .coefficients
                .iter()
                .rev()
                .fold(Real::zero(), |first_accumulator, rows| {
                    first_accumulator * &values[0]
                        + rows
                            .iter()
                            .rev()
                            .fold(Real::zero(), |second_accumulator, row| {
                                second_accumulator * &values[1]
                                    + polynomial_evaluate(row, &values[2])
                            })
                })
        };

        for (retained_axis, substituted_axis) in [(0, 1), (0, 2), (1, 2), (1, 0), (2, 0), (2, 1)] {
            let remaining_axis = 3 - retained_axis - substituted_axis;
            let reduced = trivariate_substitute_affine_axis(
                &polynomial,
                retained_axis,
                substituted_axis,
                &scale,
                &offset,
            )
            .expect("the bounded affine substitution must fit");
            let mut values = std::array::from_fn(|_| Real::zero());
            values[retained_axis] = retained_value.clone();
            values[substituted_axis] = &scale * &retained_value + &offset;
            values[remaining_axis] = remaining_value.clone();
            let reduced_value = polynomial_evaluate(
                &bivariate_specialize_second(&reduced, &remaining_value),
                &retained_value,
            );
            assert_eq!(reduced_value, evaluate_trivariate(&values));
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn trivariate_binary_axis_substitutions_preserve_all_axis_orders() {
        let polynomial = TrivariatePolynomial2 {
            coefficients: (0..3)
                .map(|first| {
                    (0..4)
                        .map(|second| {
                            (0..2)
                                .map(|third| Real::from(1_i32 + first * 7 + second * 3 + third * 5))
                                .collect()
                        })
                        .collect()
                })
                .collect(),
        };
        let left_value = (Real::from(2_i8) / Real::from(5_i8)).unwrap();
        let right_value = (Real::from(4_i8) / Real::from(7_i8)).unwrap();
        let evaluate_trivariate = |values: &[Real; 3]| {
            polynomial
                .coefficients
                .iter()
                .rev()
                .fold(Real::zero(), |first_accumulator, rows| {
                    first_accumulator * &values[0]
                        + rows
                            .iter()
                            .rev()
                            .fold(Real::zero(), |second_accumulator, row| {
                                second_accumulator * &values[1]
                                    + polynomial_evaluate(row, &values[2])
                            })
                })
        };

        for (left_axis, right_axis, result_axis) in [
            (0, 1, 2),
            (1, 0, 2),
            (0, 2, 1),
            (2, 0, 1),
            (1, 2, 0),
            (2, 1, 0),
        ] {
            let reduced =
                trivariate_substitute_product_axis(&polynomial, left_axis, right_axis, result_axis)
                    .expect("the bounded product substitution must fit");
            let mut values = std::array::from_fn(|_| Real::zero());
            values[left_axis] = left_value.clone();
            values[right_axis] = right_value.clone();
            values[result_axis] = &left_value * &right_value;
            let reduced_value = polynomial_evaluate(
                &bivariate_specialize_second(&reduced, &right_value),
                &left_value,
            );
            assert_eq!(reduced_value, evaluate_trivariate(&values));

            let reduced =
                trivariate_substitute_sum_axis(&polynomial, left_axis, right_axis, result_axis)
                    .expect("the bounded sum substitution must fit");
            values[result_axis] = &left_value + &right_value;
            let reduced_value = polynomial_evaluate(
                &bivariate_specialize_second(&reduced, &right_value),
                &left_value,
            );
            assert_eq!(reduced_value, evaluate_trivariate(&values));
        }
    }

    #[cfg(feature = "predicates")]
    fn nonaffine_three_field_chord_fixture() -> ([BezierParameter2; 3], TrivariatePolynomial2) {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let parameters = [
            algebraic_parameter(vec![-half, Real::zero(), Real::one()]),
            algebraic_parameter(vec![-third, Real::zero(), Real::one()]),
            algebraic_parameter(vec![
                Real::one(),
                Real::zero(),
                Real::from(-10_i8),
                Real::zero(),
                Real::one(),
            ]),
        ];
        // a*b-c*(a+b), where c=a*b/(a+b).
        let mut coefficients = vec![vec![vec![Real::zero(); 2]; 2]; 2];
        coefficients[1][1][0] = Real::one();
        coefficients[1][0][1] = -Real::one();
        coefficients[0][1][1] = -Real::one();
        (parameters, TrivariatePolynomial2 { coefficients })
    }

    #[cfg(feature = "predicates")]
    fn trivariate_multiply_axis_linear(
        polynomial: TrivariatePolynomial2,
        axis: usize,
        constant: &Real,
        linear: &Real,
    ) -> TrivariatePolynomial2 {
        let dimensions = polynomial.dimensions();
        let mut counts = [dimensions.0, dimensions.1, dimensions.2];
        counts[axis] += 1;
        let mut coefficients = vec![vec![vec![Real::zero(); counts[2]]; counts[1]]; counts[0]];
        for (first, rows) in polynomial.coefficients.iter().enumerate() {
            for (second, row) in rows.iter().enumerate() {
                for (third, coefficient) in row.iter().enumerate() {
                    let exponents = [first, second, third];
                    coefficients[first][second][third] += coefficient * constant;
                    let mut incremented = exponents;
                    incremented[axis] += 1;
                    coefficients[incremented[0]][incremented[1]][incremented[2]] +=
                        coefficient * linear;
                }
            }
        }
        TrivariatePolynomial2 { coefficients }
    }

    #[cfg(feature = "predicates")]
    fn trivariate_multiply(
        left: &TrivariatePolynomial2,
        right: &TrivariatePolynomial2,
    ) -> TrivariatePolynomial2 {
        let left_dimensions = left.dimensions();
        let right_dimensions = right.dimensions();
        let counts = [
            left_dimensions.0 + right_dimensions.0 - 1,
            left_dimensions.1 + right_dimensions.1 - 1,
            left_dimensions.2 + right_dimensions.2 - 1,
        ];
        let mut coefficients = vec![vec![vec![Real::zero(); counts[2]]; counts[1]]; counts[0]];
        for (left_first, left_rows) in left.coefficients.iter().enumerate() {
            for (left_second, left_row) in left_rows.iter().enumerate() {
                for (left_third, left_coefficient) in left_row.iter().enumerate() {
                    for (right_first, right_rows) in right.coefficients.iter().enumerate() {
                        for (right_second, right_row) in right_rows.iter().enumerate() {
                            for (right_third, right_coefficient) in right_row.iter().enumerate() {
                                coefficients[left_first + right_first]
                                    [left_second + right_second][left_third + right_third] +=
                                    left_coefficient * right_coefficient;
                            }
                        }
                    }
                }
            }
        }
        TrivariatePolynomial2 { coefficients }
    }

    #[cfg(feature = "predicates")]
    fn trivariate_multi_affine(coefficients: [i8; 8]) -> TrivariatePolynomial2 {
        TrivariatePolynomial2 {
            coefficients: (0..2)
                .map(|first| {
                    (0..2)
                        .map(|second| {
                            (0..2)
                                .map(|third| {
                                    Real::from(coefficients[first * 4 + second * 2 + third])
                                })
                                .collect()
                        })
                        .collect()
                })
                .collect(),
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn quadratic_axis_factorization_replays_dense_multi_affine_products() {
        for (left, right) in [
            ([1, 2, -1, 3, 2, -2, 4, 1], [2, -1, 3, 1, -3, 2, 1, 2]),
            ([-2, 1, 2, -1, 3, 1, -2, 4], [1, 3, -2, 2, 1, -1, 3, -2]),
        ] {
            let product = trivariate_multiply(
                &trivariate_multi_affine(left),
                &trivariate_multi_affine(right),
            );
            for axis in 0..3 {
                let factorizations = trivariate_quadratic_axis_factorizations(&product, axis)
                    .expect("every authored linear-axis product must split exactly");
                assert!(factorizations.iter().all(|(factor, quotient)| {
                    trivariate_multiply(factor, quotient).coefficients == product.coefficients
                }));
            }
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn repeated_cubic_axis_factorization_replays_double_and_triple_factors() {
        let repeated = trivariate_multi_affine([1, 2, -1, 3, 2, -2, 4, 1]);
        let other = trivariate_multi_affine([2, -1, 3, 1, -3, 2, 1, 2]);
        let repeated_square = trivariate_multiply(&repeated, &repeated);
        for product in [
            trivariate_multiply(&other, &repeated_square),
            trivariate_multiply(&repeated, &repeated_square),
        ] {
            for axis in 0..3 {
                let factorizations = trivariate_repeated_cubic_axis_factorizations(&product, axis)
                    .expect("every authored repeated linear-axis factor must split exactly");
                assert!(factorizations.iter().all(|(factor, quotient)| {
                    trivariate_multiply(factor, quotient).coefficients == product.coefficients
                }));
            }
        }
    }

    #[cfg(feature = "predicates")]
    #[test]
    fn repeated_cubic_axis_factorization_rejects_a_square_free_cubic() {
        let mut polynomial = TrivariatePolynomial2 {
            coefficients: vec![vec![vec![Real::one()]]],
        };
        // This arithmetic-progression cubic makes the repeated-root formula
        // propose its middle root, but that factor occurs only once.
        for constant in [Real::one(), Real::from(2_i8), Real::from(3_i8)] {
            polynomial = trivariate_multiply_axis_linear(polynomial, 0, &constant, &Real::one());
        }
        assert!(trivariate_repeated_cubic_axis_factorizations(&polynomial, 0).is_none());
    }

